function resolvePlugins(config: RawConfig): PluginSpec[] {
  const plugins: PluginSpec[] = [];
  if (config.plugins) {
    for (const entry of config.plugins) {
      if (typeof entry === "string") {
        plugins.push({ name: entry, options: {} });
      } else {
        if (entry.enabled !== false) {
          if (entry.name.startsWith("@internal/")) {
            plugins.push({ name: entry.name, options: entry.options ?? {}, internal: true });
          } else {
            plugins.push({ name: entry.name, options: entry.options ?? {} });
          }
        }
      }
    }
  }
  return plugins;
}

