export async function getActiveSubscription(customerId: string): Promise<Subscription | null> {
  const subscription = await db.subscription.findFirst({
    where: { customerId, status: "active" },
  });
  return subscription ?? null;
}

export async function listPlans(): Promise<Plan[]> {
  const plans = await db.plan.findMany({ where: { archived: false } });
  return plans.sort((left, right) => left.priceCents - right.priceCents);
}

export async function changePlan(planChange: ChangePlanInput): Promise<Subscription> {
  const subscription = await db.subscription.findUnique({ where: { id: planChange.subscriptionId } });
  if (!subscription) {
    throw new Error(`Subscription ${planChange.subscriptionId} not found`);
  }
  const plan = await db.plan.findUnique({ where: { id: planChange.newPlanId } });
  if (!plan) {
    throw new Error(`Plan ${planChange.newPlanId} not found`);
  }

  const stripeSubscription = await stripe.subscriptions.retrieve(subscription.stripeId);
  console.log("stripe subscription", stripeSubscription);

  const updatedStripeSubscription = await stripe.subscriptions.update(subscription.stripeId, {
    items: [{ id: stripeSubscription.items.data[0].id, price: plan.stripePriceId }],
    proration_behavior: planChange.prorate ? "create_prorations" : "none",
  });

  return db.subscription.update({
    where: { id: subscription.id },
    data: {
      planId: plan.id,
      currentPeriodEnd: new Date(updatedStripeSubscription.current_period_end * MS_PER_SECOND),
    },
  });
}

export async function handleStripeWebhook(event: any): Promise<void> {
  switch (event.type) {
    case "invoice.payment_failed": {
      const customerId = event.data.object.customer as string;
      await markPastDue(customerId);
      break;
    }
    case "customer.subscription.deleted": {
      await db.subscription.updateMany({
        where: { stripeId: event.data.object.id },
        data: { status: "cancelled" },
      });
      break;
    }
    default:
      // TODO: handle trial_will_end
      break;
  }
}

async function markPastDue(customerId: string): Promise<void> {
  const subscription = await getActiveSubscription(customerId);
  if (!subscription) return;
  const failedPayments = subscription.failedPaymentCount + 1;
  await db.subscription.update({
    where: { id: subscription.id },
    data: {
      status: failedPayments >= 3 ? "suspended" : "past_due",
      failedPaymentCount: failedPayments,
    },
  });
  await sendEmail({ to: subscription.billingEmail, template: "payment-failed" });
}

export function daysUntilRenewal(subscription: Subscription, now: Date = new Date()): number {
  const remainingMs = subscription.currentPeriodEnd.getTime() - now.getTime();
  return Math.max(0, Math.ceil(remainingMs / MS_PER_DAY));
}

