import { NextResponse } from "next/server";
import { z } from "zod";
import { db } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

const createTodoSchema = z.object({
  title: z.string().trim().min(1),
  dueDate: z.coerce.date().optional(),
});

export async function GET() {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  const todos = await db.todo.findMany({ where: { ownerId: user.id }, orderBy: { createdAt: "desc" } });
  return NextResponse.json(todos);
}

export async function POST(request: Request) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  const validation = createTodoSchema.safeParse(await request.json());
  if (!validation.success) {
    return NextResponse.json({ errors: validation.error.flatten() }, { status: 400 });
  }
  const todo = await db.todo.create({ data: { ...validation.data, ownerId: user.id } });
  return NextResponse.json(todo, { status: 201 });
}

