import { useState, type FormEvent } from "react";
import { updateNotificationSettings } from "../api/settings";
import type { NotificationSettings as Settings } from "../types";

type Channel = "email" | "push" | "sms";

const CHANNEL_LABELS: Record<Channel, string> = {
  email: "Email",
  push: "Push notifications",
  sms: "Text messages",
};

const DIGEST_OPTIONS = [
  { label: "Never", frequency: "never" },
  { label: "Daily", frequency: "daily" },
  { label: "Weekly", frequency: "weekly" },
] as const;

interface NotificationSettingsProps {
  initialSettings: Settings;
  onSaved?: (settings: Settings) => void;
}

export function NotificationSettings({ initialSettings, onSaved }: NotificationSettingsProps) {
  const [settings, setSettings] = useState<Settings>(initialSettings);
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);

  const toggleChannel = (channel: Channel) => {
    setSettings((current) => ({
      ...current,
      channels: { ...current.channels, [channel]: !current.channels[channel] },
    }));
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setSaving(true);
    setSaveError(null);
    try {
      const savedSettings = await updateNotificationSettings(settings);
      onSaved?.(savedSettings);
    } catch (err) {
      setSaveError(err instanceof Error ? err.message : "Could not save settings");
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <fieldset>
        <legend className="text-sm font-medium">Where should we reach you?</legend>
        {(Object.keys(CHANNEL_LABELS) as Channel[]).map((channel) => (
          <label key={channel} className="flex items-center gap-2">
            <input
              type="checkbox"
              checked={settings.channels[channel]}
              onChange={() => toggleChannel(channel)}
            />
            {CHANNEL_LABELS[channel]}
          </label>
        ))}
      </fieldset>

      <label className="block">
        <span className="text-sm font-medium">Summary digest</span>
        <select
          value={settings.digest}
          onChange={(event) =>
            setSettings((current) => ({ ...current, digest: event.target.value as Settings["digest"] }))
          }
        >
          {DIGEST_OPTIONS.map((option) => (
            <option key={option.frequency} value={option.frequency}>
              {option.label}
            </option>
          ))}
        </select>
      </label>

      {saveError && (
        <p role="alert" className="text-sm text-red-600">
          {saveError}
        </p>
      )}

      <button type="submit" disabled={saving}>
        {saving ? "Saving…" : "Save preferences"}
      </button>
    </form>
  );
}

