import { nanoid } from "nanoid";

export interface Env {
  PASTES: KVNamespace;
  ADMIN_TOKEN: string;
}

interface StoredPaste {
  content: string;
  language: string;
  createdAt: string;
}

const PASTE_ID_LENGTH = 10;
const PASTE_TTL_SECONDS = 60 * 60 * 24 * 7;
const MAX_PASTE_BYTES = 512 * 1024;
const JSON_HEADERS = { "Content-Type": "application/json" };

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: JSON_HEADERS });
}

async function createPaste(request: Request, env: Env): Promise<Response> {
  const content = await request.text();
  if (content.length === 0) {
    return jsonResponse({ error: "Paste body is empty" }, 400);
  }
  if (new TextEncoder().encode(content).byteLength > MAX_PASTE_BYTES) {
    return jsonResponse({ error: "Paste exceeds the size limit" }, 413);
  }
  const pasteId = nanoid(PASTE_ID_LENGTH);
  const paste: StoredPaste = {
    content,
    language: new URL(request.url).searchParams.get("lang") ?? "text",
    createdAt: new Date().toISOString(),
  };
  await env.PASTES.put(pasteId, JSON.stringify(paste), { expirationTtl: PASTE_TTL_SECONDS });
  return jsonResponse({ id: pasteId }, 201);
}

async function readPaste(pasteId: string, env: Env): Promise<Response> {
  const paste = await env.PASTES.get<StoredPaste>(pasteId, "json");
  if (paste === null) {
    return jsonResponse({ error: "Paste not found" }, 404);
  }
  return jsonResponse(paste);
}

async function deletePaste(pasteId: string, request: Request, env: Env): Promise<Response> {
  const authorization = request.headers.get("Authorization");
  if (authorization !== `Bearer ${env.ADMIN_TOKEN}`) {
    return jsonResponse({ error: "Unauthorized" }, 401);
  }
  await env.PASTES.delete(pasteId);
  return new Response(null, { status: 204 });
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const { pathname } = new URL(request.url);
    const [, resource, pasteId] = pathname.split("/");

    if (resource !== "pastes") {
      return jsonResponse({ error: "Not found" }, 404);
    }
    if (request.method === "POST" && !pasteId) {
      return createPaste(request, env);
    }
    if (request.method === "GET" && pasteId) {
      return readPaste(pasteId, env);
    }
    if (request.method === "DELETE" && pasteId) {
      return deletePaste(pasteId, request, env);
    }
    return jsonResponse({ error: "Method not allowed" }, 405);
  },
};

