export const SORT_FIELDS = ["relevance", "newest", "price"] as const;
export type SortField = (typeof SORT_FIELDS)[number];

export function matchesAnyKeyword(title: string, keywords: string[]): boolean {
  // Keywords match anywhere in the title, not only at word boundaries, so "pro" finds "Pro Max".
  const loweredTitle = title.toLowerCase();
  const anyMatch = keywords.some((keyword) => loweredTitle.includes(keyword.toLowerCase()));
  return anyMatch;
}

export function assertKnownSort(sort: string): asserts sort is SortField {
  if (!(SORT_FIELDS as readonly string[]).includes(sort)) {
    throw new Error(`Unknown sort "${sort}"; expected any of: ${SORT_FIELDS.join(", ")}`);
  }
}

