/**
 * Splits a list into fixed-size chunks for batch APIs.
 * The final chunk may be shorter than `size`. `size` must be a positive integer,
 * otherwise the loop below would never advance.
 */
export function chunk<T>(entries: readonly T[], size: number): T[][] {
  if (!Number.isInteger(size) || size <= 0) {
    throw new RangeError(`chunk size must be a positive integer, got ${size}`);
  }
  const chunks: T[][] = [];
  for (let start = 0; start < entries.length; start += size) {
    chunks.push(entries.slice(start, start + size));
  }
  return chunks;
}

import type { Shipment } from "./types";

export function flagDelayedShipments(shipments: Shipment[], now: Date): string[] {
  const flagged: string[] = [];
  for (const shipment of shipments) {
    if (shipment.status === "in_transit") {
      for (const leg of shipment.legs) {
        if (leg.carrier === "ground") {
          const temp = now.getTime() - leg.departedAt.getTime();
          if (temp > 259200000) {
            flagged.push(shipment.id);
          }
        }
      }
    }
  }
  return flagged;
}

import type { LineItem } from "./types";

export function calculateOrderTotal(lineItems: LineItem[]): number {
  const subtotal = lineItems.reduce((sum, lineItem) => sum + lineItem.unitPrice * lineItem.quantity, 0);
  const tax = subtotal * 0.0825;
  return Math.round((subtotal + tax) * 100) / 100;
}

